import{_ as t,o as i,c as a,ag as r}from"./chunks/framework.Ccn6roXv.js";const u=JSON.parse('{"title":"10. A simple testing mindset","description":"How to test server functions by checking security properties in order.","frontmatter":{"title":"10. A simple testing mindset","description":"How to test server functions by checking security properties in order."},"headers":[],"relativePath":"guide/10-testing-mindset.md","filePath":"guide/10-testing-mindset.md"}'),s={name:"guide/10-testing-mindset.md"};function o(n,e,l,d,p,h){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="a-simple-testing-mindset" tabindex="-1">A simple testing mindset <a class="header-anchor" href="#a-simple-testing-mindset" aria-label="Permalink to &quot;A simple testing mindset&quot;">​</a></h1><p>Testing is easier when you follow the same order as the request pipeline.</p><p>Start with the property you want to verify. Then choose a small request change that tests that property.</p><h2 id="step-1-identify-the-action" tabindex="-1">Step 1: Identify the action <a class="header-anchor" href="#step-1-identify-the-action" aria-label="Permalink to &quot;Step 1: Identify the action&quot;">​</a></h2><p>Ask what the server function does.</p><p>Examples:</p><ul><li>Reads data</li><li>Updates a profile</li><li>Creates a record</li><li>Sends a message</li><li>Changes permissions</li></ul><p>State-changing actions deserve more caution.</p><h2 id="step-2-identify-trusted-inputs" tabindex="-1">Step 2: Identify trusted inputs <a class="header-anchor" href="#step-2-identify-trusted-inputs" aria-label="Permalink to &quot;Step 2: Identify trusted inputs&quot;">​</a></h2><p>Ask where identity, role, tenant, account, and object ownership come from.</p><p>These should come from server-side session or database state.</p><h2 id="step-3-identify-parsed-request-data" tabindex="-1">Step 3: Identify parsed request data <a class="header-anchor" href="#step-3-identify-parsed-request-data" aria-label="Permalink to &quot;Step 3: Identify parsed request data&quot;">​</a></h2><p>Ask what fields the handler receives after validation.</p><p>Look for extra fields, loose schemas, coercion, and unknown values.</p><h2 id="step-4-modify-one-thing" tabindex="-1">Step 4: Modify one thing <a class="header-anchor" href="#step-4-modify-one-thing" aria-label="Permalink to &quot;Step 4: Modify one thing&quot;">​</a></h2><p>Change one property at a time.</p><p>Examples:</p><ul><li>Add an unexpected field</li><li>Change a type</li><li>Remove a required field</li><li>Change a role-like value</li><li>Change a dynamic field name</li></ul><p>Record whether the request fails during decoding, validation, authorization, or handler logic.</p><h2 id="step-5-check-the-result" tabindex="-1">Step 5: Check the result <a class="header-anchor" href="#step-5-check-the-result" aria-label="Permalink to &quot;Step 5: Check the result&quot;">​</a></h2><p>Good failures are boring.</p><p>Look for:</p><ul><li>No state change</li><li>No privileged effect</li><li>No stack trace</li><li>No internal details</li><li>A clear but generic error</li></ul><h2 id="where-tools-fit" tabindex="-1">Where tools fit <a class="header-anchor" href="#where-tools-fit" aria-label="Permalink to &quot;Where tools fit&quot;">​</a></h2><p>After you understand the model, tools save time.</p><p>Use <code>tss-codec</code> to decode and re-encode server function traffic. Use the security lab to practice against intentional vulnerable patterns.</p><h2 id="security-property" tabindex="-1">Security property <a class="header-anchor" href="#security-property" aria-label="Permalink to &quot;Security property&quot;">​</a></h2><p>The property to preserve is measurable behavior:</p><ul><li>The server rejects unsafe input.</li><li>The server explains only what the caller should know.</li><li>The server state remains correct after tampering.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Use the appendices for wire details, decoded examples, test cases, and tooling notes.</p>',31)])])}const f=t(s,[["render",o]]);export{u as __pageData,f as default};
